import torch
import torch_npu
import custom_ops_lib

class ModelNew(torch.nn.Module):
    """
    Optimized model: keep GEMM and GroupNorm in PyTorch, fuse min+bias add into AscendC kernel.
    """
    def __init__(self, in_features, out_features, num_groups, bias_shape):
        super(ModelNew, self).__init__()
        self.gemm = torch.nn.Linear(in_features, out_features)
        self.group_norm = torch.nn.GroupNorm(num_groups, out_features)
        self.bias = torch.nn.Parameter(torch.randn(bias_shape))

    def forward(self, x):
        # x: (N, in_features)
        x = self.gemm(x)                         # (N, out_features)
        x = self.group_norm(x)                   # (N, out_features)
        x_min = torch.min(x, dim=1, keepdim=True)[0]  # (N, 1)
        # reshape and expand to match bias (1, C, 1, 1) => result (N, C, 1, 1)
        n = x_min.shape[0]
        c = self.bias.shape[1]
        x_min_4d = x_min.view(n, 1, 1, 1).expand(n, c, 1, 1).contiguous()
        bias_exp = self.bias.expand(n, c, 1, 1).contiguous()
        y = custom_ops_lib.gemm_group_norm_min_bias_add_custom(x_min_4d, bias_exp)
        return y
